1	// Baremetal correctness check for the Q1_0 RVV kernels on sim_ax45mpv_premium
2	// (VLEN=512, no zfh/zvfh). q1_0.c / q1_0.h are copies of
3	// /home/nick/work/llama.cpp/kernel-lab/ - edit there first, then re-copy.
4	// Slim harness: no argv (crt0 passes none), tiny sizes (RTL sim ~6 kHz).
5	// Exit code = number of failed checks (0 = pass).
6	#include "q1_0.h"
7	
8	#include <math.h>
9	#include <stdio.h>
10	#include <string.h>
11	
12	#include <riscv_vector.h>
13	
14	#define NORM_ERR_MAX 1e-4
15	#define N_MAX 512
16	
17	static block_q1_0 x[N_MAX / QK1_0];
18	static block_q8_0 y[N_MAX / QK8_0];
19	
20	static uint64_t rng_state = 0x243F6A8885A308D3ull;
21	
22	static uint64_t rng_next(void) {
23	    rng_state ^= rng_state << 13;
24	    rng_state ^= rng_state >> 7;
25	    rng_state ^= rng_state << 17;
26	    return rng_state;
27	}
28	
29	static uint16_t rand_fp16(float lo, float hi) {
30	    const float v = lo + (hi - lo) * ((rng_next() >> 11) * 0x1.0p-53f);
31	    return lab_fp32_to_fp16(v);
32	}
33	
34	static void fill_random(int nbx, int nby) {
35	    for (int i = 0; i < nbx; ++i) {
36	        x[i].d = rand_fp16(-2.0f, 2.0f);
37	        for (int j = 0; j < QK1_0 / 8; ++j) {
38	            x[i].qs[j] = (uint8_t)rng_next();
39	        }
40	    }
41	    for (int i = 0; i < nby; ++i) {
42	        y[i].d = rand_fp16(0.001f, 1.0f);
43	        for (int j = 0; j < QK8_0; ++j) {
44	            y[i].qs[j] = (int8_t)((int)(rng_next() % 255) - 127); // [-127,127], never -128
45	        }
46	    }
47	}
48	
49	static double ref_dot_double(int n, double * sum_abs) {
50	    double sum = 0.0, sabs = 0.0;
51	    for (int i = 0; i < n / QK1_0; ++i) {
52	        const double d0 = (double)lab_fp16_to_fp32(x[i].d);
53	        for (int k = 0; k < 4; ++k) {
54	            const block_q8_0 * yb = &y[i * 4 + k];
55	            const double d1 = (double)lab_fp16_to_fp32(yb->d);
56	            long sumi = 0;
57	            for (int j = 0; j < QK8_0; ++j) {
58	                const int bit = (x[i].qs[k * 4 + j / 8] >> (j % 8)) & 1;
59	                sumi += bit ? yb->qs[j] : -yb->qs[j];
60	            }
61	            sum  += d0 * d1 * (double)sumi;
62	            sabs += fabs(d0 * d1 * (double)sumi);
63	        }
64	    }
65	    *sum_abs = sabs;
66	    return sum;
67	}
68	
69	static uint32_t f32_bits(float f) {
70	    uint32_t w;
71	    memcpy(&w, &f, sizeof(w));
72	    return w;
73	}
74	
75	typedef void (*vec4_t)(int, float *, const void *, const void *);
76	
77	static void gen4(int n, float * s, const void * vx, const void * vy) {
78	    ggml_vec_dot_q1_0_q8_0_generic(n, s, 0, vx, 0, vy, 0, 1);
79	}
80	static void disp4(int n, float * s, const void * vx, const void * vy) {
81	    ggml_vec_dot_q1_0_q8_0(n, s, 0, vx, 0, vy, 0, 1);
82	}
83	
84	static int check_case(int n, const char * name) {
85	    float ref;
86	    gen4(n, &ref, x, y);
87	    double sabs = 0.0;
88	    const double dref = ref_dot_double(n, &sabs);
89	    const double norm = sabs > 1e-30 ? sabs : 1e-30;
90	
91	    static const struct { const char * nm; vec4_t fn; int bitexact; } ks[] = {
92	        {"vl256",  ggml_vec_dot_q1_0_q8_0_vl256,  1},
93	        {"vl128",  ggml_vec_dot_q1_0_q8_0_vl128,  1},
94	        {"vl512",  ggml_vec_dot_q1_0_q8_0_vl512,  0},
95	        {"vl512w", ggml_vec_dot_q1_0_q8_0_vl512w, 0},
96	        {"disp",   disp4,                         0},
97	    };
98	
99	    int failed = 0;
100	    for (unsigned i = 0; i < sizeof(ks) / sizeof(ks[0]); ++i) {
101	        float got;
102	        ks[i].fn(n, &got, x, y);
103	        if (ks[i].bitexact && f32_bits(got) != f32_bits(ref)) {
104	            printf("FAIL %s %s n=%d bits ref=0x%08x got=0x%08x\n",
105	                   ks[i].nm, name, n, (unsigned)f32_bits(ref), (unsigned)f32_bits(got));
106	            failed++;
107	        }
108	        const double err = fabs((double)got - dref) / norm;
109	        if (err > NORM_ERR_MAX) {
110	            printf("FAIL %s %s n=%d norm_err=%g\n", ks[i].nm, name, n, err);
111	            failed++;
112	        }
113	    }
114	    return failed;
115	}
116	
117	int main(void) {
118	    printf("q1_0 rvv check: VLEN=%lu\n", (unsigned long)(__riscv_vlenb() * 8));
