// ---- benchmark (instruction-count proxy under QEMU) ------------------------

static int test_bench(void) {
    const int n = 8192;
    const int reps = 2000;
    const int nbx = n / QK1_0;
    const int nby = n / QK8_0;
    block_q1_0 * x = malloc((size_t)nbx * sizeof(block_q1_0));
    block_q8_0 * y = malloc((size_t)nby * sizeof(block_q8_0));
    fill_random(x, nbx, y, nby);

    const size_t vlen = runtime_vlen();
    double base_ns = 0.0;

    printf("bench: n=%d, reps=%d (QEMU: proxy for instruction count only)\n", n, reps);
    for (int ki = 0; ki < n_kernels; ++ki) {
        const struct kernel_ent * k = &kernels[ki];
        if (k->is_dispatcher || vlen < k->min_vlen) {
            continue;
        }
        float s = 0;
        k->fn(n, &s, 0, x, 0, y, 0, 1); // warm up

        struct timespec t0, t1;
        clock_gettime(CLOCK_MONOTONIC, &t0);
        for (int r = 0; r < reps; ++r) {
            k->fn(n, &s, 0, x, 0, y, 0, 1);
        }
        clock_gettime(CLOCK_MONOTONIC, &t1);
        const double ns = (double)(t1.tv_sec - t0.tv_sec) * 1e9 + (double)(t1.tv_nsec - t0.tv_nsec);
        const double per_call = ns / reps;
        if (base_ns == 0.0) {
            base_ns = per_call;
        }
        printf("  %-8s %10.0f ns/row  speedup vs %s: %.2fx  (result %.6g)\n",
               k->name, per_call, kernels[1].name, base_ns / per_call, (double)s);
    }

    // scalar reference for context
    {
        float s = 0;
        struct timespec t0, t1;
        clock_gettime(CLOCK_MONOTONIC, &t0);
        for (int r = 0; r < reps / 10; ++r) {
            ggml_vec_dot_q1_0_q8_0_generic(n, &s, 0, x, 0, y, 0, 1);
        }
        clock_gettime(CLOCK_MONOTONIC, &t1);
        const double ns = (double)(t1.tv_sec - t0.tv_sec) * 1e9 + (double)(t1.tv_nsec - t0.tv_nsec);
        printf("  %-8s %10.0f ns/row\n", "generic", ns / (reps / 10));
    }

    free(x);
    free(y);

    // F4 proxy on the K=51 decode shape (2560x1024): whole-matrix GEMV,
    // per-row vec_dot dispatcher vs row-parallel gemv dispatcher
    {
        const int gn = 1024, gnr = 2560;
        const int gnb = gn / QK1_0;
        block_q1_0      * gx     = malloc((size_t)gnr * gnb * sizeof(block_q1_0));
        block_q8_0      * gy     = malloc((size_t)(gn / QK8_0) * sizeof(block_q8_0));
        block_q1_0_64x1 * bricks = malloc((size_t)(gnr / Q1_NX1_N) * gnb * sizeof(block_q1_0_64x1));
        float           * out    = malloc((size_t)gnr * sizeof(float));
        fill_random(gx, gnr * gnb, gy, gn / QK8_0);
        repack_q1_0_to_q1_0_64x1(gx, bricks, gnr, gn);

        const int greps = 5;
        struct timespec t0, t1;

        clock_gettime(CLOCK_MONOTONIC, &t0);
        for (int r = 0; r < greps; ++r) {
            for (int row = 0; row < gnr; ++row) {
                ggml_vec_dot_q1_0_q8_0(gn, &out[row], 0, gx + (size_t)row * gnb, 0, gy, 0, 1);
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &t1);
        const double ns_dot = ((double)(t1.tv_sec - t0.tv_sec) * 1e9 + (double)(t1.tv_nsec - t0.tv_nsec)) / greps;

        clock_gettime(CLOCK_MONOTONIC, &t0);
        for (int r = 0; r < greps; ++r) {
            gemv_q1_0_64x1_q8_0(gn, out, bricks, gy, gnr);
        }
        clock_gettime(CLOCK_MONOTONIC, &t1);
        const double ns_gemv = ((double)(t1.tv_sec - t0.tv_sec) * 1e9 + (double)(t1.tv_nsec - t0.tv_nsec)) / greps;

        printf("  K=51 shape %dx%d: per-row vec_dot %.0f us, gemv_64x1 %.0f us, ratio %.2fx\n",
               gnr, gn, ns_dot / 1e3, ns_gemv / 1e3, ns_dot / ns_gemv);

        free(gx); free(gy); free(bricks); free(out);
    }
    return 0;
}

