// a cheap smoke check. Exit code 0 = pass.
#include "q1_0.h"

#include <math.h>
#include <stdio.h>

static unsigned long rdcycle(void) {
    unsigned long r;
    asm volatile("fence rw, rw" ::: "memory");
    asm volatile("csrr %0, mcycle" : "=r"(r));
    return r;
}

#ifndef Q1_VLEN
