23	float lab_fp16_to_fp32(uint16_t h) {
24	    const uint32_t w = (uint32_t) h << 16;
25	    const uint32_t sign = w & UINT32_C(0x80000000);
26	    const uint32_t two_w = w + w;
27	
28	    const uint32_t exp_offset = UINT32_C(0xE0) << 23;
29	    const float exp_scale = 0x1.0p-112f;
30	    const float normalized_value = fp32_from_bits((two_w >> 4) + exp_offset) * exp_scale;
31	
32	    const uint32_t magic_mask = UINT32_C(126) << 23;
33	    const float magic_bias = 0.5f;
34	    const float denormalized_value = fp32_from_bits((two_w >> 17) | magic_mask) - magic_bias;
35	
36	    const uint32_t denormalized_cutoff = UINT32_C(1) << 27;
37	    const uint32_t result = sign |
38	        (two_w < denormalized_cutoff ? fp32_to_bits(denormalized_value) : fp32_to_bits(normalized_value));
39	    return fp32_from_bits(result);
40	}
41	
42	uint16_t lab_fp32_to_fp16(float f) {
43	    const float scale_to_inf  = 0x1.0p+112f;
44	    const float scale_to_zero = 0x1.0p-110f;
45	    float base = (fabsf(f) * scale_to_inf) * scale_to_zero;
46	
47	    const uint32_t w = fp32_to_bits(f);
48	    const uint32_t shl1_w = w + w;
49	    const uint32_t sign = w & UINT32_C(0x80000000);
50	    uint32_t bias = shl1_w & UINT32_C(0xFF000000);
51	    if (bias < UINT32_C(0x71000000)) {
52	        bias = UINT32_C(0x71000000);
53	    }
54	
55	    base = fp32_from_bits((bias >> 1) + UINT32_C(0x07800000)) + base;
56	    const uint32_t bits = fp32_to_bits(base);
57	    const uint32_t exp_bits = (bits >> 13) & UINT32_C(0x00007C00);
58	    const uint32_t mantissa_bits = bits & UINT32_C(0x00000FFF);
59	    const uint32_t nonsign = exp_bits + mantissa_bits;
60	    return (sign >> 16) | (shl1_w > UINT32_C(0xFF000000) ? UINT16_C(0x7E00) : nonsign);
61	}
62	
63	// ---- 1. scalar reference (ggml quants.c generic, simplified signature) ----
64	
65	void q1_0_dot_scalar(int n, float * s, const block_q1_0 * x, const block_q8_0 * y) {
66	    const int nb = n / QK1_0;
67	    assert(n % QK1_0 == 0);
68	
69	    float sumf = 0.0f;
70	
71	    for (int i = 0; i < nb; i++) {
72	        const float d0 = lab_fp16_to_fp32(x[i].d);
73	
74	        float sumi = 0.0f;
75	
76	        for (int k = 0; k < 4; k++) {
77	            const block_q8_0 * yb = &y[i * 4 + k];
78	            const float d1 = lab_fp16_to_fp32(yb->d);
79	            int sumi_block = 0;
80	
81	            const uint8_t * bits = &x[i].qs[k * 4];
82	            const int8_t  * qy   = yb->qs;
83	
84	            for (int b = 0; b < 4; ++b, qy += 8) {
85	                const unsigned mask = bits[b];
86	                sumi_block += ((mask & 0x01) ? qy[0] : -qy[0])
87	                           +  ((mask & 0x02) ? qy[1] : -qy[1])
88	                           +  ((mask & 0x04) ? qy[2] : -qy[2])
89	                           +  ((mask & 0x08) ? qy[3] : -qy[3])
90	                           +  ((mask & 0x10) ? qy[4] : -qy[4])
91	                           +  ((mask & 0x20) ? qy[5] : -qy[5])
92	                           +  ((mask & 0x40) ? qy[6] : -qy[6])
93	                           +  ((mask & 0x80) ? qy[7] : -qy[7]);
94	            }
95	
96	            sumi += d1 * (float)sumi_block;
97	        }
98	
99	        sumf += d0 * sumi;
100	    }
101	
102	    *s = sumf;
103	}
104	
105	// ---- 2. original production kernel (arch/riscv quants.c vl256) ------------
106	// per 32-group: vlm mask + vmerge(+-y) + vwredsum 32->1 + vmv.x.s + scalar FMA
107	
108	void q1_0_dot_vl256(int n, float * s, const block_q1_0 * x, const block_q8_0 * y) {
109	    const int nb = n / QK1_0;
110	    assert(n % QK1_0 == 0);
111	
112	    const size_t vl32 = __riscv_vsetvl_e8m1(32);
113	    assert(vl32 == 32);
114	
115	    const vint16m1_t zero = __riscv_vmv_v_x_i16m1(0, 1);
116	
117	    float sumf = 0;
118	
119	    for (int ib = 0; ib < nb; ++ib) {
120	        const float d0 = lab_fp16_to_fp32(x[ib].d);
121	
122	        float acc = 0;
123	
124	        for (int k = 0; k < 4; ++k) {
125	            const block_q8_0 * yb = &y[ib * 4 + k];
126	            const vbool8_t is_not_zero = __riscv_vlm_v_b8(x[ib].qs + 4 * k, vl32);
127	
128	            const vint8m1_t qy = __riscv_vle8_v_i8m1(yb->qs, vl32);
129	            const vint8m1_t neg_qy = __riscv_vneg_v_i8m1(qy, vl32);
