131	
132	            const vint16m1_t red = __riscv_vwredsum_vs_i8m1_i16m1(sy, zero, vl32);
133	            acc += lab_fp16_to_fp32(yb->d) * (float)__riscv_vmv_x_s_i16m1_i16(red);
134	        }
135	
136	        sumf += d0 * acc;
137	    }
