1	// ISA acceptance probe for the premium RTL: tries each FP vector op class the
2	// Q1_0 gemv needs, at each LMUL, in ONE run. A private trap handler SKIPS
3	// illegal instructions (mepc += 4) and counts them, so every case reports
4	// "ok" or "TRAP" instead of the first trap killing the run.
5	#include <stdint.h>
6	#include <stdio.h>
7	#include <riscv_vector.h>
8	
9	unsigned long probe_traps;   // bumped by the skip handler
10	
11	__attribute__((naked, aligned(4))) void probe_trap_handler(void) {
12	    asm volatile(
13	        "addi  sp, sp, -16\n"
14	        "sd    t0, 0(sp)\n"
15	        "sd    t1, 8(sp)\n"
16	        "csrr  t0, mepc\n"
17	        "addi  t0, t0, 4\n"        // all probed insns are 4-byte
18	        "csrw  mepc, t0\n"
19	        "la    t1, probe_traps\n"
20	        "ld    t0, 0(t1)\n"
21	        "addi  t0, t0, 1\n"
22	        "sd    t0, 0(t1)\n"
23	        "ld    t0, 0(sp)\n"
24	        "ld    t1, 8(sp)\n"
25	        "addi  sp, sp, 16\n"
26	        "mret\n");
27	}
28	
29	static unsigned long check(const char * name) {
30	    static unsigned long last;
31	    const unsigned long now = probe_traps;
32	    iprintf("%-28s %s\n", name, now == last ? "ok" : "TRAP");
33	    const unsigned long delta = now - last;
34	    last = now;
35	    return delta;
36	}
37	
38	int main(void) {
39	    iprintf("probe: vlenb=%lu\n", (unsigned long)__riscv_vlenb());
40	    asm volatile("csrw mtvec, %0" :: "r"(probe_trap_handler));
41	
42	    // vector FP always uses frm (dynamic rounding); an uninitialized/reserved
43	    // frm makes EVERY vector-FP op illegal while integer vector works fine.
44	    // The BSP crt0 enables mstatus.FS but never writes fcsr - do it here.
45	    asm volatile("csrw fcsr, zero");
46	
47	    // scalar FP warm-up: drive mstatus.FS Initial -> Dirty before any vector
48	    // FP. Hypothesis: this RTL gates vector-FP on FS=Dirty (in the shootout,
49	    // vfmv.v.f passed only after the vl256 loop had run scalar FP).
50	    {   volatile float wf = 1.5f;
51	        wf = wf * 2.0f + 0.25f;
52	        (void)wf; }
53	    check("scalar FP warm-up");
54	
55	    static int32_t  ibuf[64];
56	    static int16_t  sbuf[64];
57	    static float    fbuf[64];
58	    for (int i = 0; i < 64; ++i) { ibuf[i] = i - 32; sbuf[i] = (int16_t)(i - 32); fbuf[i] = 0; }
59	
60	    // --- int -> float converts, single width, each LMUL ---------------------
61	    {   vint32m1_t s = __riscv_vle32_v_i32m1(ibuf, 16);
62	        vfloat32m1_t f = __riscv_vfcvt_f_x_v_f32m1(s, 16);
63	        __riscv_vse32_v_f32m1(fbuf, f, 16); }
64	    check("vfcvt.f.x.v m1");
65	
66	    {   vint32m2_t s = __riscv_vle32_v_i32m2(ibuf, 32);
67	        vfloat32m2_t f = __riscv_vfcvt_f_x_v_f32m2(s, 32);
68	        __riscv_vse32_v_f32m2(fbuf, f, 32); }
69	    check("vfcvt.f.x.v m2");
70	
71	    {   vint32m4_t s = __riscv_vle32_v_i32m4(ibuf, 64);
72	        vfloat32m4_t f = __riscv_vfcvt_f_x_v_f32m4(s, 64);
73	        __riscv_vse32_v_f32m4(fbuf, f, 64); }
74	    check("vfcvt.f.x.v m4");
75	
76	    // --- widening int16 -> float32 ------------------------------------------
77	    {   vint16m1_t s = __riscv_vle16_v_i16m1(sbuf, 32);
78	        vfloat32m2_t f = __riscv_vfwcvt_f_x_v_f32m2(s, 32);
79	        __riscv_vse32_v_f32m2(fbuf, f, 32); }
80	    check("vfwcvt.f.x.v m1->m2");
81	
82	    {   vint16m2_t s = __riscv_vle16_v_i16m2(sbuf, 64);
83	        vfloat32m4_t f = __riscv_vfwcvt_f_x_v_f32m4(s, 64);
84	        __riscv_vse32_v_f32m4(fbuf, f, 64); }
85	    check("vfwcvt.f.x.v m2->m4");
86	
87	    // --- float arithmetic at m2 / m4 ----------------------------------------
88	    {   vfloat32m2_t a = __riscv_vfmv_v_f_f32m2(1.5f, 32);
89	        a = __riscv_vfmacc_vf_f32m2(a, 2.0f, a, 32);
90	        __riscv_vse32_v_f32m2(fbuf, a, 32); }
91	    check("vfmacc.vf m2");
92	
93	    {   vfloat32m4_t a = __riscv_vfmv_v_f_f32m4(1.5f, 64);
94	        a = __riscv_vfmacc_vf_f32m4(a, 2.0f, a, 64);
95	        __riscv_vse32_v_f32m4(fbuf, a, 64); }
96	    check("vfmacc.vf m4");
97	
98	    {   vfloat32m4_t a = __riscv_vfmv_v_f_f32m4(1.5f, 64);
99	        a = __riscv_vfmacc_vv_f32m4(a, a, a, 64);
100	        __riscv_vse32_v_f32m4(fbuf, a, 64); }
101	    check("vfmacc.vv m4");
102	
103	    {   vfloat32m4_t a = __riscv_vfmv_v_f_f32m4(3.0f, 64);
104	        vfloat32m4_t b = __riscv_vfmv_v_f_f32m4(1.0f, 64);
105	        a = __riscv_vfsub_vv_f32m4(a, b, 64);
106	        __riscv_vse32_v_f32m4(fbuf, a, 64); }
107	    check("vfsub.vv m4");
108	
109	    {   vfloat32m4_t a = __riscv_vfmv_v_f_f32m4(3.0f, 64);
110	        a = __riscv_vfsub_vf_f32m4(a, 1.0f, 64);
111	        __riscv_vse32_v_f32m4(fbuf, a, 64); }
112	    check("vfsub.vf m4");
113	
114	    // sanity: a genuinely-supported op must NOT report TRAP
115	    {   vint32m4_t s = __riscv_vle32_v_i32m4(ibuf, 64);
116	        s = __riscv_vadd_vx_i32m4(s, 3, 64);
117	        __riscv_vse32_v_i32m4(ibuf, s, 64); }
118	    check("vadd.vx m4 (control)");
119	
120	    iprintf("total traps: %lu\n", probe_traps);
121	    return 0;
122	}
