42	namespace fs = std::filesystem;
43	
44	namespace andes_sim {
45	namespace {
46	
47	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
48	// success; on failure prints an error tagged with `ctx` and returns "". The
49	// existence check is here, at the one resolver fast/cycle/cycle-gdb share, so a
50	// missing path fails with a clear "ELF not found" instead of being handed to the
51	// engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS"). Mirrors the
52	// up-front check run_hybrid already does.
53	std::string abs_elf(const std::string& path, const std::string& ctx) {
54	  std::error_code ec;
55	  fs::path abs = fs::absolute(path, ec);
56	  if (ec) {
57	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
58	                 ctx.c_str(), path.c_str());
59	    return "";
60	  }
61	  if (!fs::is_regular_file(abs, ec)) {
62	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
63	                 path.c_str());
64	    return "";
65	  }
66	  return abs.string();
67	}
68	
69	// Validate the lone-ELF positional shape the standalone models require: print
70	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
71	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
72	// spawns a --describe subprocess per Verilator build). `model` labels the error.
73	int check_one_elf(const Cli& cli, const char* model) {
74	  if (cli.positional.empty()) {
75	    std::fprintf(stderr,
76	                 "andesim run --mode %s: missing ELF (the workload to run; "
77	                 "e.g. a tests/fixtures/<name>.elf)\n",
78	                 model);
79	    return 2;
80	  }
81	  if (cli.positional.size() > 1) {
82	    std::fprintf(stderr,
83	                 "andesim run --mode %s: unexpected argument '%s' "
84	                 "(engine args go after --)\n",
85	                 model, cli.positional[1].c_str());
86	    return 2;
87	  }
88	  return 0;
89	}
90	
91	// --runtime linux staging shared by fast and hybrid: manifest + stage the
92	// vlinux-run.elf that boots `app_elf` under the proxy kernel. On success
93	// returns the staged boot ELF and logs the one staged line; on failure prints
94	// "<ctx>: <why>" and returns "" (the caller's exit-2 path). `ctx` is each
95	// mode's full diagnostic prefix, passed verbatim -- they are asymmetric (fast
96	// says "--runtime linux", hybrid's early-fail prefix does not).
97	std::string stage_linux_boot(const std::string& app_elf, uint64_t mem_bytes,
98	                             const std::vector<std::string>& passthrough,
99	                             const char* ctx) {
100	  std::string stage_err;
101	  const std::string boot_elf =
102	      stage_linux_runtime(app_elf, mem_bytes, passthrough, stage_err);
103	  if (boot_elf.empty()) {
104	    std::fprintf(stderr, "%s: %s\n", ctx, stage_err.c_str());
105	    return "";
106	  }
107	  log_line(kLogInfo, "[andesim] --runtime linux: staged %s (app=%s)",
108	           boot_elf.c_str(), app_elf.c_str());
109	  return boot_elf;
110	}
111	
112	// A failed plan's diagnostics, shared by the main hybrid run and the --verify
113	// oracle run: the error line under `ctx`, then where run_plan kept the L2
114	// repro bundle (when one was written). The callers keep their own return 1
115	// (and the main run its log-file hint).
116	void report_plan_failure(const char* ctx, const PlanResult& r) {
117	  std::fprintf(stderr, "%s: %s\n", ctx, r.error.c_str());
118	  if (!r.repro_dir.empty())
119	    std::fprintf(stderr,
120	                 "[andesim] repro: kept run artifacts at %s "
121	                 "(see manifest.txt)\n",
122	                 r.repro_dir.c_str());
123	}
124	
125	// elf_engine_arch_error (the ELF-vs-engine width guard shared with profile)
126	// lives in engine_registry.hpp, next to resolve_accurate_engine.
127	
128	// print_dry_run (the shared --dry-run preview) lives in argv.hpp, next to
129	// render_argv.
130	
131	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
132	// and verbose [info] log (VsimFilter), relaying only the program's own output
133	// and any real diagnostics, then restate the lifted cycle count as andesim's own
134	// one-line result under the [andesim] prefix. The count is printed AFTER the run
135	// (the engine logs it at exit), so it follows the program output. Returns the
136	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
137	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
138	int run_cycle_clean(const std::vector<std::string>& argv) {
139	  VsimFilter filter;
140	  const int rc = run_line_filtered(
141	      argv, [&filter](int stream, std::string_view line) {
142	        std::FILE* dst = nullptr;
143	        switch (filter.classify(stream, line)) {
144	          case VsimFilter::Dest::kStdout: dst = stdout; break;
145	          case VsimFilter::Dest::kStderr: dst = stderr; break;
146	          case VsimFilter::Dest::kDrop: return;
147	        }
148	        std::fwrite(line.data(), 1, line.size(), dst);
149	        std::fputc('\n', dst);
150	      });
151	  if (const std::optional<uint64_t> c = filter.cycles())
152	    log_result(kLogInfo, "[andesim] %llu cycles",
153	               static_cast<unsigned long long>(*c));
154	  return rc;
155	}
156	
157	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
158	// then run the resolved engine standalone with `extra` (model flags the
159	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
160	// `clean_output` picks how the engine's output is presented: fast inherits the
161	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
162	// semihosting console works unchanged); cycle filters out the engine's banner +
163	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
164	// exit code propagates. The per-model engine + selection are resolved by the
165	// caller; `model` here only labels the positional diagnostics.
166	// `boot_elf_override`: --runtime linux (U2) boots a staged vlinux.elf instead
167	// of the positional ELF (which stays the APP path -- still validated to
168	// exist, still what the manifest embeds); empty means "boot the ELF as given"
169	// (every other caller).
170	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
171	                   const char* model, const std::vector<std::string>& extra = {},
172	                   bool clean_output = false,
173	                   const std::string& boot_elf_override = {}) {
174	  if (int rc = check_one_elf(cli, model)) return rc;
175	  // QEMU's -bios flag searches its data directory for relative paths rather
176	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
177	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
178	  if (elf.empty()) return 2;
179	  const std::string& boot_elf =
180	      boot_elf_override.empty() ? elf : boot_elf_override;
181	  std::vector<std::string> args = extra;
182	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
183	  std::string err;
184	  const std::vector<std::string> argv =
185	      passthrough_argv(eng, "standalone", boot_elf, args, err);
186	  if (!err.empty()) {
187	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
188	    return 2;
189	  }
190	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
191	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
192	  if (cli.dry_run)
193	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
194	  // Trace mirrors the hybrid legs' exec lines: emitted BEFORE the spawn, so a
195	  // wedged engine still leaves the exact command in the log.
196	  log_line(kLogTrace, "[andesim] exec standalone [%s]: %s", eng.id.c_str(),
197	           render_argv(argv).c_str());
198	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
199	}
200	
201	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
202	// only the built-in qemu descriptor, so it resolves that directly rather than
203	// discover_engines(), which would spawn a --describe subprocess per Verilator
204	// build only to discard them all here.
205	int run_fast(const Cli& cli) {
206	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
207	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
208	    std::fprintf(stderr,
209	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
210	                 "got '%s'\n",
211	                 cli.engine.c_str());
212	    return 2;
213	  }
214	  // --runtime linux (U2, ROADMAP_LINUX_RUNTIME.md) defaults --mem-size to 1G
215	  // (the app + vlinux's own arenas) when the user did not pick one.
216	  std::string mem_size_spec = cli.mem_size;
217	  if (cli.runtime == "linux" && mem_size_spec.empty()) mem_size_spec = "1G";
218	
219	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
220	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
221	  std::string err;
222	  std::vector<std::string> extra = qemu_m_args(mem_size_spec, err);
223	  if (!err.empty()) {
224	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
225	    return 2;
226	  }
227	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
228	  if (cli.gdb) {
229	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
230	    extra.push_back("-gdb");
231	    extra.push_back("tcp::" + port);
232	    extra.push_back("-S");
233	  }
234	
235	  // --runtime linux: stage a manifested vlinux.elf that boots the app under
236	  // the proxy kernel. The ELF positional is the APP, not the boot image --
237	  // -bios loads the staged vlinux instead (run_standalone's boot_elf_override).
238	  Cli cli2 = cli;
239	  std::string boot_elf;
240	  if (cli.runtime == "linux") {
241	    if (int rc = check_one_elf(cli, "fast")) return rc;
242	    const std::string app_elf =
243	        abs_elf(cli.positional[0], "--mode fast --runtime linux");
244	    if (app_elf.empty()) return 2;
245	
246	    // mem_size_spec already passed qemu_m_args above (whole-MiB check, a
247	    // strictly tighter validation than parse_size alone), so this call
248	    // cannot fail: reused only to get the byte count for the manifest.
249	    const long long mem_bytes = parse_size(mem_size_spec, err);
250	
251	    boot_elf = stage_linux_boot(app_elf, static_cast<uint64_t>(mem_bytes),
252	                                cli.passthrough,
253	                                "andesim run --mode fast --runtime linux");
254	    if (boot_elf.empty()) return 2;
255	
256	    // App argv (ROADMAP_LINUX_RUNTIME.md U8) travels through the manifest
257	    // above, not QEMU's own CLI -- clear it here so QEMU never sees it as
258	    // engine flags (e.g. "-m x.gguf" is not a memory size).
259	    cli2.passthrough.clear();
260	
261	    // Engine-synced CPU: the app + vlinux run on the hardware a hybrid
262	    // measurement targets, not the ax46 vplat default (last -cpu wins).
263	    extra.push_back("-cpu");
264	    extra.push_back("andes-ax45mpv,vlen=512");
265	  }
266	
267	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
268	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
269	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
270	  // ELF -- the override is the user's call.
271	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
272	  int xlen;
273	  if (cli.engine == kQemuId32) xlen = 32;
274	  else if (cli.engine == kQemuId64) xlen = 64;
275	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
276	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
277	  // == elf_w), so this guard already implies an explicit --engine.
278	  if (elf_w && elf_w != xlen)
279	    std::fprintf(stderr,
280	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
281	                 "(running as rv%d)\n",
282	                 cli.engine.c_str(), xlen, elf_w, xlen);
283	  return run_standalone(cli2, builtin_qemu_arch(xlen), "fast", extra,
284	                        /*clean_output=*/false, boot_elf);
285	}
