287	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
288	// its --jtag-port only after it has reset and halted the hart, so the debugger we
289	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
290	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
291	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
292	// single debugger slot). Returns false on timeout.
293	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
294	  constexpr int kPollMs = 50;
295	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
296	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
297	      char line[512];
298	      while (std::fgets(line, sizeof line, f)) {
299	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
300	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
301	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
302	        unsigned lport = 0, st = 0;
303	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
304	            && st == 0x0A && lport == port) {
305	          std::fclose(f);
306	          return true;
307	        }
308	      }
309	      std::fclose(f);
310	    }
311	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
312	  }
313	  return false;
314	}
