316	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
317	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
318	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
319	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
320	  const char* iceman = std::getenv("ICEMAN");
321	  if (!iceman || !*iceman) {
322	    std::fprintf(stderr,
323	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
324	                 "(export ICEMAN=<path to ICEman binary>)\n");
325	    return 2;
326	  }
327	  // Build vsim argv from the standalone template, appending user passthrough
328	  // and the JTAG port flag.
329	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
330	  if (elf.empty()) return 2;
331	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
332	  std::vector<std::string> vsim_pass = cli.passthrough;
333	  vsim_pass.push_back("--jtag-port");
334	  vsim_pass.push_back(jtag_port);
335	  std::string err;
336	  const std::vector<std::string> vsim_argv =
337	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
338	  if (!err.empty()) {
339	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
340	    return 2;
341	  }
342	  std::fprintf(stderr,
343	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
344	               jtag_port.c_str());
345	  if (fork_background(vsim_argv) < 0) {
346	    std::fprintf(stderr,
347	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
348	    return 1;
349	  }
350	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
351	  // Wait for the port to be LISTENing before launching the debugger (it does not
352	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
353	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
354	  // but launch anyway if it never appears.
355	  if (const int pnum = std::atoi(jtag_port.c_str());
356	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
357	    std::fprintf(stderr,
358	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
359	                 "after 20s; launching the debugger anyway\n",
360	                 jtag_port.c_str());
361	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
362	  // localhost, port 9104) instead of its default real-hardware adapter; without
363	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
364	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
365	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
366	}
