368	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
369	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
370	// engine's own output. Unlike fast, this must discover the Verilator build(s)
371	// to resolve the engine (explicit --engine, else the sole one).
372	int run_accurate(const Cli& cli) {
373	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
374	  // --describe subprocess per Verilator build only to fail on the argument.
375	  if (int rc = check_one_elf(cli, "cycle")) return rc;
376	  // --mem-size is validated but has nothing to size: the cycle engine always
377	  // models its full DRAM window. Say so instead of silently ignoring it.
378	  if (!cli.mem_size.empty()) {
379	    std::string se;
380	    if (parse_size(cli.mem_size, se); !se.empty()) {
381	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
382	                   se.c_str());
383	      return 2;
384	    }
385	    log_line(kLogWarn,
386	             "[andesim] --mem-size: the cycle engine models its full "
387	             "DRAM window; nothing to size");
388	  }
389	  Discovery disc = discover_engines();
390	  const EngineDescriptor* eng = resolve_accurate_engine_or_report(
391	      disc, cli.engine, "andesim run --mode cycle");
392	  if (!eng) return 2;
393	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
394	  // vice versa) cannot run. Catch it here with a clear message instead of the
395	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
396	  // positional.
397	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
398	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
399	    return 2;
400	  }
401	  // --dry-run previews the standalone command and spawns nothing, so it takes
402	  // precedence over the interactive --gdb path (a dry run launches no debugger).
403	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
404	  // clean_output: hide vsim's banner + [info] log, restate the cycle count under
405	  // [andesim] (fast keeps raw passthrough -- QEMU has no such banner and its
406	  // monitor/gdbstub are interactive).
407	  return run_standalone(cli, *eng, "cycle", /*extra=*/{}, /*clean_output=*/true);
408	}
