410	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
411	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
412	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
413	// driver's tests/e2e.sh delegation with a single window-cycle line.
414	int run_hybrid(const Cli& cli) {
415	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
416	  auto fail = [](const std::string& msg) {
417	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
418	    return 2;
419	  };
420	
421	  // --print-memmap: the map describes the run's window (engine + --mem-size),
422	  // not a workload, so the ELF is optional (when given it only adds the
423	  // fit-vs-scratch note) and the trigger machinery is skipped entirely.
424	  const bool memmap_only = cli.print_memmap;
425	  if (!memmap_only) {
426	    if (int rc = check_one_elf(cli, "hybrid")) return rc;
427	  } else if (cli.positional.size() > 1) {
428	    return fail("unexpected argument '" + cli.positional[1] + "'");
429	  }
430	
431	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
432	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
433	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
434	  std::string elf_path;
435	  if (!cli.positional.empty()) {
436	    elf_path = abs_elf(cli.positional[0], "--mode hybrid");
437	    if (elf_path.empty()) return 2;
438	  }
439	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
440	
441	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
442	  // mistake fails fast without spawning a --describe per Verilator build.
443	  std::string err;
444	  Trigger trig;
445	  std::vector<std::string> vsim_extras;
446	  if (!memmap_only) {
447	    trig = hybrid_trigger(cli, elf_path, err);
448	    if (!err.empty()) return fail(err);
449	
450	    // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
451	    // hybrid triggers; unknown returned an error above) -- exactly the entry
452	    // boundary --verify needs the oracle to arm on.
453	    vsim_extras = vsim_extra_args(cli, trig.kind, err);
454	    if (!err.empty()) return fail(err);
455	  }
456	
457	  // --runtime linux (U9) defaults --mem-size to 1G, same as fast (U2) --
458	  // the app + vlinux's own arenas need more than the plain hybrid default.
459	  long long mem = cli.runtime == "linux" ? 1024LL * 1024 * 1024
460	                                         : 128LL * 1024 * 1024;
461	  if (!cli.mem_size.empty()) {
462	    std::string se;
463	    mem = parse_size(cli.mem_size, se);
464	    if (!se.empty()) return fail("--mem-size: " + se);
465	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
466	    // guest RAM here. The physical mmap reserves one V-scratch page above the
467	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
468	    // page. Failing now beats allocating a huge mmap file first and letting
469	    // QEMU die late.
470	    if (mem > max_program_mem_bytes())
471	      return fail("--mem-size " + cli.mem_size +
472	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
473	                  "reservation)");
474	  }
475	
476	  // L26/F3: refuse a run whose static image would extend into the reserved
477	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
478	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
479	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
480	  // scratch -> silent corruption. Derive the page's start from
481	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
482	  // `mem`, so the threshold tracks the reservation shape instead of relying on
483	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
484	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
485	  // reports it.
486	  {
487	    std::string e;
488	    const uint64_t top = elf_load_top(elf_path, e);
489	    const uint64_t scratch_gpa =
490	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
491	    if (e.empty() && top > scratch_gpa) {
492	      char msg[256];
493	      std::snprintf(msg, sizeof(msg),
494	                    "ELF static image ends at 0x%llx, overlapping the reserved "
495	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
496	                    "; raise --mem-size or shrink the image",
497	                    static_cast<unsigned long long>(top),
498	                    static_cast<unsigned long long>(scratch_gpa));
499	      return fail(msg);
500	    }
501	  }
502	
503	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
504	  // or the sole cycle-accurate engine (reusing the F8 selector).
505	  Discovery disc = discover_engines();
506	  const EngineDescriptor* acc = resolve_accurate_engine_or_report(
507	      disc, cli.engine, "andesim run --mode hybrid");
508	  if (!acc) return 2;
509	
510	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
511	  // cannot share architectural state with the rv64 fast leg).
512	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
513	  // ...and the ELF must match that engine width too (same guard as cycle).
514	  if (std::string e = elf_engine_arch_error(elf_path, *acc); !e.empty())
515	    return fail(e);
516	
517	  if (memmap_only) {
518	    // The LM/HVM bases come from the same probe run_plan stages as the fast
519	    // leg's -readconfig, so the printed geometry IS the run's effective one.
520	    // Tolerant like stage_qemu_cfg: a probe failure only drops the LM rows
521	    // (hybrid_memmap warns).
522	    const std::string cfg = probe_qemu_cfg(acc->bin_path);
523	    std::fprintf(stderr, "[andesim] hybrid memory map: engine=%s mem-size=%s\n",
524	                 acc->id.c_str(),
525	                 fmt_size(static_cast<uint64_t>(mem)).c_str());
526	    std::fputs(render_memmap(hybrid_memmap(*acc, mem, cfg)).c_str(), stdout);
527	    // With an ELF given, say where its static image lands in that window.
528	    // Always "fits DRAM": an ELF whose image reached the V-scratch page was
529	    // already rejected by the L26/F3 overlap guard above (scratch_gpa == mem).
530	    if (!elf_path.empty()) {
531	      std::string e;
532	      const uint64_t top = elf_load_top(elf_path, e);
533	      if (e.empty())
534	        std::printf("ELF %s: static image top 0x%llx (fits DRAM)\n",
535	                    elf.stem().string().c_str(),
536	                    static_cast<unsigned long long>(top));
537	    }
538	    return 0;
539	  }
540	
541	  // --runtime linux (U9): stage a manifested vlinux.elf that boots the app
542	  // under the proxy kernel, same as run_fast -- but here BOTH legs share
543	  // plan.elf (Plan's own contract: "the ELF every leg launches"), so
544	  // staging once and pointing plan.elf at the result covers the fast-
545	  // forward QEMU leg AND the vsim accurate leg with no per-leg special
546	  // casing. PC-mode triggers already resolved --pc-start/--pc-end against
547	  // elf_path (the app's own ELF, correctly) BEFORE this point -- vlinux's
548	  // own symbol table would have been the wrong one for that lookup.
549	  std::string boot_elf = elf_path;
550	  if (cli.runtime == "linux") {
551	    boot_elf = stage_linux_boot(elf_path, static_cast<uint64_t>(mem),
552	                                cli.passthrough, "andesim run --mode hybrid");
553	    if (boot_elf.empty()) return 2;
554	  }
555	
556	  Plan plan;
557	  plan.elf = boot_elf;
558	  plan.mem_size = mem;
559	  Step qemu_step{kQemuId64, "fast-leg", trig};
560	  Step vsim_step{acc->id, "accurate-leg", trig};
561	  // --runtime linux + marker mode: vsim's OWN trigger only static-pre-scans
562	  // whatever ELF it is handed (hybrid::CsrTrigger::scan_buffer, vsim_andesim
563	  // src/hybrid/csr_trigger.hpp) -- but under --runtime linux vsim boots
564	  // vlinux-run.elf, and the marker HINTs are in the APP's ELF, which vlinux
565	  // only loads into memory at RUNTIME (never part of vlinux-run.elf's own
566	  // static PT_LOAD content). QEMU1's plugin has no such limitation (a TCG
567	  // plugin watches the EXECUTED instruction stream, content-agnostic), which
568	  // is why only vsim's leg needs a workaround here. Fix: resolve the exit
569	  // marker's PC by scanning elf_path (the app's real ELF) on the driver
570	  // side, using the SAME shared predicate vsim's own scanner uses
571	  // (hybrid/insn_match.h -- bit-for-bit the same match, not a reimplementation
572	  // that could drift), and feed it to vsim through the EXISTING PC-mode
573	  // trigger machinery (`--hybrid-exit-pc`, already wired for --trigger pc)
574	  // instead of marker mode. QEMU1 keeps ordinary marker-mode unchanged (its
575	  // detection already works); only vsim's own trigger config changes. This
576	  // needs ZERO changes to vsim's own source, matching the roadmap's explicit
577	  // "hybrid transport, triggers, plugin, resume driver, and engines need NO
578	  // changes" constraint.
579	  if (cli.runtime == "linux" && trig.kind == "marker") {
580	    const RoiMarkerPcs m = find_roi_markers(elf_path);
581	    if (m.exit_pc == 0)
582	      return fail("no ROI exit marker (slti x0,x0,0x5A1) found in " + elf_path +
583	                  " -- add <andesim/ROI.h>'s andesim_ROI_begin()/end() around "
584	                  "the region to measure");
585	    char pcbuf[32];
586	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
587	                  static_cast<unsigned long long>(m.exit_pc));
588	    vsim_step.trigger = Trigger{"pc", {{"exit_pc", pcbuf}}};
589	  }
590	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
591	  // #1: with no --verify the driver consumes only the vsim mcycle delta, so ask
592	  // the accurate leg to drain just the counters and skip the full register-file
593	  // readback (~190 DM abstract commands). --verify keeps the full drain so the
594	  // oracle diff sees every field. Driver policy lives here next to the rest of
595	  // the verify reasoning, not in vsim_extra_args (user-forwarded flags only).
596	  if (!cli.verify)
597	    vsim_step.extra_args.push_back("--drain-minimal");
598	  // L4: the vsim leg speaks the same --log-level scale; forward ours so one
599	  // flag tunes the whole pipeline (its stderr is relayed at <= debug).
600	  vsim_step.extra_args.push_back("--log-level");
601	  vsim_step.extra_args.push_back(std::to_string(log_threshold()));
602	  plan.steps = {qemu_step, vsim_step};
603	
604	  // Banner to stderr so the window-cycle result stands alone on stdout.
605	  // vlen is the synced value the fast leg inherits from the engine.
606	  log_line(kLogDebug,
607	           "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s",
608	           acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
609	           elf.stem().string().c_str());
610	  // L3 decision log: why THIS engine.
611	  log_line(kLogDebug, "[andesim] engine: %s (%s)", acc->id.c_str(),
612	           cli.engine.empty() ? "sole cycle-accurate engine"
613	                              : "selected by --engine");
614	
615	  PlanOptions opts;
616	  opts.dry_run = cli.dry_run;
617	  if (!parse_positive_int(cli.step_timeout_ms, opts.timeout_ms, opts.timeout_ms))
618	    return fail("--step-timeout-ms: not a positive integer: " +
619	                cli.step_timeout_ms);
620	  const PlanResult r = run_plan(plan, disc.engines, opts);
621	  if (!r.ok()) {
622	    report_plan_failure("andesim run --mode hybrid", r);
623	    if (!log_file_path().empty())
624	      std::fprintf(stderr, "[andesim] repro: full log at %s\n",
625	                   log_file_path().c_str());
626	    return 1;
627	  }
628	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
629	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
630	  // then the vsim accurate leg -- and stop. Nothing was spawned.
631	  if (cli.dry_run) {
632	    std::vector<std::string> labels;
633	    labels.reserve(plan.steps.size());
634	    for (const Step& s : plan.steps)
635	      labels.push_back(s.role + " [" + s.engine_id + "]");
636	    return print_dry_run(r.argvs, labels);
637	  }
638	  // Relay each leg's stdout: the program's own prints (QEMU1 phase-1 output,
639	  // then anything the ROI wrote on vsim) belong to the user. The vsim
640	  // (accurate) leg's output is prefixed by vsim's startup banner (Copyright /
641	  // Version) -- strip it so only real program output shows, the same as `cycle`
642	  // does; its [info] log is already absent (the leg's stderr was dropped at
643	  // capture). The QEMU leg has no banner, so it relays verbatim.
644	  for (size_t i = 0; i < r.phases.size(); ++i) {
645	    const std::string& out = r.phases[i].out;
646	    if (out.empty()) continue;
647	    if (i < plan.steps.size() && plan.steps[i].role == "accurate-leg") {
648	      const std::string shown = strip_vsim_banner(out);
649	      std::fwrite(shown.data(), 1, shown.size(), stdout);
650	    } else {
651	      std::fwrite(out.data(), 1, out.size(), stdout);
652	    }
653	  }
654	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
655	  // vsim mcycle delta.
656	  {
657	    const unsigned long long q_mc = r.phases[0].mcycle;
658	    const unsigned long long v_mc = r.phases[1].mcycle;
659	    // The answer line, same shape as cycle mode; the raw mcycle operands are
660	    // debug detail.
661	    log_result(kLogInfo, "[andesim] %llu cycles", v_mc - q_mc);
662	    log_result(kLogDebug,
663	               "[andesim] window: trigger=%s vsim mcycle=%llu qemu mcycle=%llu",
664	               trig.kind.c_str(), v_mc, q_mc);
665	  }
666	
667	  // v6 incompatibility surface: the QEMU1 drain's write-mask records which
668	  // config CSRs the program actually wrote; any of them this engine does not
669	  // implement would TRAP on its silicon (the program would never reach the
670	  // ROI), yet the hybrid restore silently skipped it. Warn -- the figure may
671	  // not represent this engine running this program.
672	  {
673	    const std::string w = unsupported_written_warning(
674	        r.phases[0].st, acc->andes_csrs, acc->id);
675	    if (!w.empty() && log_on(kLogWarn)) std::fputs(w.c_str(), stderr);
676	  }
677	
678	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
679	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
680	  // halt pc, and diff the two drains in-process. The oracle plan gets its
681	  // own fresh mmap: reusing the main run's would boot the oracle on the
682	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
683	  // output was already relayed from the main run.
684	  if (cli.verify) {
685	    char pcbuf[32];
686	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
687	                  static_cast<unsigned long long>(r.phases[1].st.pc));
688	    Trigger vtrig;
689	    vtrig.kind = "verify-" + trig.kind;
690	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
691	    vtrig.params["drain_pc"] = pcbuf;
692	
693	    Plan vplan;
694	    vplan.elf = elf_path;
695	    vplan.mem_size = mem;
696	    vplan.steps = {Step{kQemuId64, "fast-leg", vtrig}};
697	    // The oracle must model the same hardware as the main run's accurate
698	    // engine ({vlen}/{qemu_cpu}/-readconfig sync) -- without this it ran the
699	    // family-default CPU and false-diffed on vlenb (and, on an H-capable
700	    // engine, on mideleg's read-only-one delegation bits).
701	    vplan.hw_engine_id = acc->id;
702	
703	    log_line(kLogDebug,
704	             "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
705	             "exit, pc=%s)",
706	             pcbuf);
707	    const PlanResult vr = run_plan(vplan, disc.engines);
708	    if (!vr.ok()) {
709	      report_plan_failure("andesim run --verify", vr);
710	      return 1;
711	    }
712	    // Pass the cycle engine's supported Andes-CSR list so verify skips CSRs the
713	    // engine does not implement (it never restored/re-read them; comparing
714	    // would false-diff). Mirrors the resume/drain gating in vsim.
715	    const DiffReport d =
716	        diff_states(vr.phases[0].st, r.phases[1].st, acc->andes_csrs);
717	    print_diff_report(d);
718	    if (!d.ok()) {
719	      std::fprintf(stderr,
720	                   "andesim run --verify: vsim drain diverges from the "
721	                   "QEMU oracle\n");
722	      return 1;
723	    }
724	    log_result(kLogInfo, "[verify] PASS: vsim drain matches the QEMU oracle");
725	  }
726	
727	  log_result(kLogDebug, "PASS: --mode hybrid --trigger %s (%s)",
728	             trig.kind.c_str(), elf.stem().string().c_str());
729	  return 0;
730	}
731	
732	}  // namespace
733	
734	int cmd_run(const Cli& cli) {
735	  if (cli.model.empty()) {
736	    std::fprintf(stderr,
737	                 "andesim run: --mode fast|cycle|hybrid is required "
738	                 "(pick the composition; see 'andesim run --help')\n");
739	    return 2;
740	  }
741	  if (!find_model(cli.model)) {
742	    std::fprintf(stderr,
743	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
744	                 cli.model.c_str());
745	    return 2;
746	  }
747	  // --runtime selects a proxy-kernel payload atop the chosen model
748	  // (ROADMAP_LINUX_RUNTIME.md). Only "linux" exists, and only --mode fast
749	  // and hybrid are wired (U2, U9) -- cycle has no roadmap need for it.
750	  if (!cli.runtime.empty() && cli.runtime != "linux") {
751	    std::fprintf(stderr, "andesim run: unknown --runtime '%s' (want 'linux')\n",
752	                 cli.runtime.c_str());
753	    return 2;
754	  }
755	  if (!cli.runtime.empty() && cli.model != "fast" && cli.model != "hybrid") {
756	    std::fprintf(stderr,
757	                 "andesim run: --runtime linux is supported only with "
758	                 "--mode fast or hybrid (not cycle)\n");
759	    return 2;
760	  }
761	  if (!cli.gdb_port.empty() && !cli.gdb) {
762	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
763	    return 2;
764	  }
765	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
766	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
767	  if (cli.gdb && cli.model == "hybrid") {
768	    std::fprintf(stderr,
769	                 "andesim run: --gdb is not supported with --mode hybrid\n");
770	    return 2;
771	  }
772	  // --print-memmap prints the HYBRID composition's guest memory map (the
773	  // regions both engines support across the handoff); fast/cycle run one
774	  // engine's native map, which andesim does not model.
775	  if (cli.print_memmap && cli.model != "hybrid") {
776	    std::fprintf(stderr,
777	                 "andesim run: --print-memmap requires --mode hybrid (it "
778	                 "prints the hybrid-supported guest memory map)\n");
779	    return 2;
780	  }
781	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
782	  // composition has a second engine to check.
783	  if (cli.verify && cli.model != "hybrid") {
784	    std::fprintf(stderr,
785	                 "andesim run: --verify requires --mode hybrid (the %s "
786	                 "model has nothing to cross-check)\n",
787	                 cli.model.c_str());
788	    return 2;
789	  }
790	  // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
791	  // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
792	  // handoff builds itself, so there is no single "the engine" to forward to.
793	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
794	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
795	  // Exception: --runtime linux's `-- <args>` are APP argv (ROADMAP_LINUX_RUNTIME.md
796	  // U8/U9), not engine flags for either leg -- they thread into the manifest
797	  // both legs' staged vlinux-run.elf shares, so they are meaningful here too.
798	  if (!cli.passthrough.empty() && cli.model == "hybrid" && cli.runtime != "linux") {
799	    std::fprintf(stderr,
800	                 "andesim run: --mode hybrid takes no `-- <args>` (the handoff "
801	                 "builds both legs' command lines; use --kanata/--objdump for "
802	                 "vsim options, or --mode fast|cycle to forward to one engine)\n");
803	    return 2;
804	  }
805	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window. --trigger
806	  // is hybrid-only; --pc-start/--pc-end belong to --trigger pc specifically. Any
807	  // other mode/trigger would SILENTLY drop them and hand back a figure for the
808	  // wrong window (fast/cycle: the whole program; hybrid+marker: the marker
809	  // window), so reject instead of measuring something the user did not ask for.
810	  if (!cli.trigger.empty() && cli.model != "hybrid") {
811	    std::fprintf(stderr,
812	                 "andesim run: --trigger applies only to --mode hybrid "
813	                 "(the ROI delimiter); fast/cycle run the whole program\n");
814	    return 2;
815	  }
816	  if (!cli.pc_end.empty() && cli.trigger != "pc") {
817	    std::fprintf(stderr,
818	                 "andesim run: --pc-end applies only to --mode hybrid "
819	                 "--trigger pc\n");
820	    return 2;
821	  }
822	  if (!cli.pc_start.empty() && cli.trigger != "pc") {
823	    std::fprintf(stderr,
824	                 "andesim run: --pc-start applies only to --mode hybrid "
825	                 "--trigger pc\n");
826	    return 2;
827	  }
828	  if (cli.model == "fast") return run_fast(cli);
829	  if (cli.model == "cycle") return run_accurate(cli);
830	  return run_hybrid(cli);  // model validated above; only hybrid remains
831	}
832	
833	}  // namespace andes_sim
